        de: { name: 'Marienburg', description: 'Hauptsitz des Deutschen Ordens und flächenmäßig größte Backsteinburg der Welt: drei Mauerringe, gotische Säle und Rittersäle über der Nogat.', tip: 'Der Zug aus Danzig braucht etwa 40 Minuten; den schönsten Gesamtblick hast du von der Fußgängerbrücke am anderen Nogat-Ufer.' },
        fr: { name: 'Château de Malbork', description: 'La capitale de l’ordre Teutonique et le plus vaste château de brique du monde : trois enceintes, salles gothiques et réfectoires des chevaliers au-dessus de la Nogat.', tip: 'Le train depuis Gdańsk met environ 40 minutes ; la plus belle vue d’ensemble se prend depuis la passerelle sur l’autre rive de la Nogat.' },
